SELECT 
FROM TBL_TREASURY_INTEREST_RATES


        AND RATE_TYPE = #{rateType}


        AND CURRENCY_CODE = #{currencyCode}


        AND TERM_TYPE = #{termType}


        AND RATE_DATE = #{rateDate}


        AND DATA_SOURCE = #{dataSource}


        AND IS_ENABLED = #{isEnabled}


        AND ORG_ID = #{orgId}


ORDER BY RATE_DATE DESC, CREATE_TIME DESC

SELECT 
FROM TBL_TREASURY_INTEREST_RATES
WHERE RATE_TYPE = #{rateType}
  AND CURRENCY_CODE = #{currencyCode}
  AND TERM_TYPE = #{termType}
  AND RATE_DATE = #{rateDate}
  AND ORG_ID = #{orgId}
ORDER BY CREATE_TIME DESC
LIMIT 1

SELECT 
FROM TBL_TREASURY_INTEREST_RATES
WHERE RATE_TYPE = #{rateType}
  AND CURRENCY_CODE = #{currencyCode}
  AND TERM_TYPE = #{termType}
  AND ORG_ID = #{orgId}
ORDER BY RATE_DATE DESC, CREATE_TIME DESC
LIMIT 1

SELECT 
FROM TBL_TREASURY_INTEREST_RATES
WHERE RATE_TYPE = #{rateType}
  AND CURRENCY_CODE = #{currencyCode}
  AND TERM_TYPE = #{termType}
  AND RATE_DATE BETWEEN #{startDate} AND #{endDate}
  AND ORG_ID = #{orgId}
ORDER BY RATE_DATE DESC

SELECT COUNT(1)
FROM TBL_TREASURY_INTEREST_RATES
WHERE RATE_TYPE = #{rateType}
  AND CURRENCY_CODE = #{currencyCode}
  AND TERM_TYPE = #{termType}
  AND RATE_DATE = #{rateDate}
  AND ORG_ID = #{orgId}

    AND RATE_ID != #{excludeId}
